fn test_encode_yes() {
	phrase := 'yes'
	expect := 'bvh'
	assert encode(phrase) == expect
}

fn test_encode_no() {
	phrase := 'no'
	expect := 'ml'
	assert encode(phrase) == expect
}

fn test_encode_omg() {
