	phrase := 'The quick brown fox jumps over the lazy dog.'
	expect := 'gsvjf rxpyi ldmul cqfnk hlevi gsvoz abwlt'
	assert encode(phrase) == expect
}

fn test_decode_exercism() {
	phrase := 'vcvix rhn'
	expect := 'exercism'
